// Lee texto desde text, caption o callback; si no hay, usa cadena vacía.
const textRaw =
  ($json?.message?.text)
  ?? ($json?.message?.caption)
  ?? ($json?.callback_query?.data)
  ?? "";

// Normaliza SIEMPRE como string
function normalize(s){
  return String(s ?? "")
    .toLowerCase()
    .normalize("NFD").replace(/[\u0300-\u036f]/g,"")
    .replace(/\s+/g," ")
    .trim();
}

function aboutRegimenIntent(t){
  const txt = normalize(t);

  const must = [
    /\bregimen fiscal\b/,
    /\bcambiar (de )?regimen\b/,
    /\balta (en )?regimen\b/,
    /\bobligac(ion|iones) (del )?regimen\b/,
    /\bresico\b|\brif\b|\bactividades? empresariales?\b|\basalariad[oa]s?\b|\barrendamiento\b/
  ];
  const interrogatives = [
    /\bcomo\b/, /\bque\b/, /\bqué\b/, /\bdonde\b/, /\bdónde\b/, /\?/,
    /\bpuedo\b/, /\bdebo\b/
  ];
  const anti = [
    /\bcomprobante fiscal\b|\bcfdi\b|\bdomicilio fiscal\b|\bejercicio fiscal\b|\bcedula (fiscal|rfc)\b/
  ];

  const hasMust = must.some(r=>r.test(txt)) || (/\bregimen\b/.test(txt) && /\bfiscal\b/.test(txt));
  const hasQ = interrogatives.some(r=>r.test(txt));
  const hasAnti = anti.some(r=>r.test(txt));

  const isRegimenQuestion = (hasMust && hasQ) && !hasAnti;
  const maybe = (!isRegimenQuestion && (/\bregimen\b|\bfiscal\b|\bresico\b|\brif\b/.test(txt)) && !hasAnti);

  return { isRegimenQuestion, maybe, txt };
}

const out = aboutRegimenIntent(textRaw);

return [{
  json: {
    ...$json,
    text_raw: textRaw,
    text_norm: out.txt,
    intent: out.isRegimenQuestion ? 'regimen_fiscal' : 'otro',
    intent_maybe: !!out.maybe
  }
}];

// 🔹 Nombre del nodo que trae los datos de Google Sheets
const EXCEL_NODE = "Get rows from sheet1"; // cámbialo si tiene otro nombre

// Trae todas las filas del sheet
const rows = $items(EXCEL_NODE).map(i => i.json);

// Construye el texto concatenado
const salida = rows
  .map(r => {
    const nombre = r.NOMBRE || r.Nombre || r.name || "Desconocido";
    const celular = r.CELULAR || r.Telefono || r.phone || "Sin número";
    return `Nombre: ${nombre}, Celular: ${celular}`;
  })
  .join(", ");

// Devuelve una sola salida con todo el texto concatenado
return [{ json: { texto_consolidado: salida } }];

// Une todo el texto extraído de varias páginas/hojas en un solo bloque
const allTexts = $input.all().map(item => item.json.FILE_TXT || item.json.text || "").join("\n\n---\n\n");

// Devuelve un único item con una sola propiedad FILE_TXT combinada
return [{
  json: {
    FILE_TXT: allTexts.trim()
  }
}];

// 🔹 Nombre del nodo que trae los datos de Google Sheets
const EXCEL_NODE = "Get rows from sheet"; // cámbialo si tiene otro nombre

// Trae todas las filas del sheet
const rows = $items(EXCEL_NODE).map(i => i.json);

// Construye el texto concatenado
const salida = rows
  .map(r => {
    const nombre = r.NOMBRE || r.Nombre || r.name || "Desconocido";
    const rfc = r.RFC || r.rfc || "Sin dato";
    const celular = r.CELULAR || r.Celular || r.Telefono || r.telefono || r["NUMERO DE TELEFONO"] || "Sin dato";

    return `Nombre: ${nombre}, RFC: ${rfc}, Celular: ${celular}`;
  })
  .join(", ");

// Devuelve una sola salida con todo el texto concatenado
return [{ json: { texto_consolidado: salida } }];
